import {emptyWorkspace,validateWorkspace,reviewWork,energyComparison,parsePriceCSV,paperBacktest,examplePrices,draftGrant,careReview,STAGES,STAGE_NAMES} from './core.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog,member,state,view='overview',rendererCleanup=()=>{},runtime=false,paperCSV=examplePrices(),toastTimer,saveTimer;
const VIEWS={overview:'Overview',workboard:'Workboard',measure:'Measure & improve',grants:'Grant Factory',scout:'LumaScout',paper:'Paper Lab',care:'LumaCare',assistant:'Luma Assistant',directory:'Discover the cohort',package:'Your free package'};
const storageKey=()=>`luma-ec-studio-v1:${member.id}`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function save(){try{localStorage.setItem(storageKey(),JSON.stringify(state));}catch{toast('Browser storage is full or unavailable. Export your workspace to preserve these changes.');}$('#work-count').textContent=state.items.filter(i=>i.stage!=='complete').length;if(runtime){clearTimeout(saveTimer);saveTimer=setTimeout(()=>api('workspace',{member:member.id,workspace:state}).catch(e=>toast('Local backup failed: '+e.message)),700);}}
function loadMember(id){member=catalog.companies.find(c=>c.id===id)||catalog.companies.find(c=>c.id==='excalis')||catalog.companies[0];try{state=validateWorkspace(JSON.parse(localStorage.getItem(storageKey())),member.id);}catch{state=emptyWorkspace(member.id);}document.title=`${member.name} · EC Strength Studio`;$('#sidebar-company').textContent=member.name;$('#sidebar-industry').textContent=member.industry;$('#monogram').textContent=member.name.replace(/[^A-Za-z]/g,'').slice(0,2).toUpperCase();history.replaceState({},'',`?member=${encodeURIComponent(member.id)}#${view}`);save();render();}
function show(next){if(!VIEWS[next])return;view=next;history.replaceState({},'',`?member=${encodeURIComponent(member.id)}#${view}`);render();window.scrollTo({top:0,behavior:'instant'});}
function heading(title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(member.name.toUpperCase())} / STRENGTH STUDIO</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="button-row">${actions}</div></div>`;}
function button(label,action,primary=false){return `<button class="btn${primary?' primary':''}" data-action="${action}">${label}</button>`;}
function sourceLinks(){return `<div class="source-list">${member.sources.slice(0,5).map((s,i)=>`<a href="${esc(s)}" target="_blank" rel="noopener noreferrer">${i===0?'Public source':`Source ${i+1}`} ↗</a>`).join('')}<span class="muted">Research reviewed September 2026</span></div>`;}
function stat(label,value,foot,icon='◈'){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function overview(){const manufacturing=member.industry==='Manufacturing';const care=member.industry==='Healthcare';const title=manufacturing?'From idea to<br>accepted part.':care?'Make every handoff<br>easier to follow.':'Make your strengths<br>easier to deliver.';const active=state.items.filter(i=>i.stage!=='complete').length;return heading(`Built around ${member.name}.`,'Your free workspace for clearer handoffs, useful automation, and measurable improvement.',button('↓ Your package','package'))+`
<section class="hero-work"><div class="hero-copy"><span class="eyebrow">YOUR STRENGTH. A CLEARER PATH FORWARD.</span><h2>${title}</h2><p>${esc(member.strength)}</p><div class="button-row">${button(manufacturing?'+ Add a design brief':'+ Add a work item','new-item',true)}${button('Review my workflow ↗','review-work')}</div></div><div class="graph-panel"><canvas id="flow-canvas" aria-label="Interactive 3D view of the five proposed workflow stages"></canvas><div class="graph-overline"><span>WORKFLOW / 3D VIEW</span><b>5 CONNECTED STAGES</b></div><div class="flow-labels">${member.workflow.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="graph-controls"><span>Suggested flow · drag to rotate</span><button id="motion-toggle" type="button">Pause motion</button></div></div></section>
<div class="stat-grid">${stat('Workflow opportunities','03','Questions to explore with the owner','↗')}${stat('Open work items',String(active),`${state.items.length} total in this browser`,'▦')}${stat('Measurement records',String(state.measurements.length),'Your observations, with source notes','⌁')}${stat('Assistant',runtime?'Connected':'Local tools',runtime?'Connected to your private runtime':'AI available in your download','✳')}</div>
<div class="two-col"><section class="panel"><div class="panel-head"><h2>Three places to make work easier</h2><span class="badge amber">TO EXPLORE</span></div><div class="panel-body">${member.hypotheses.map((h,i)=>`<article class="opportunity-row"><span class="number">0${i+1}</span><div><h3>${esc(h.question)}</h3><p>${esc(h.metric)}</p></div><button class="arrow-button" data-hypothesis="${i}" aria-label="Explore opportunity ${i+1}">↗</button></article>`).join('')}</div></section>
<section class="panel"><div class="panel-head"><h2>Your Luma toolkit</h2><span class="badge">INCLUDED</span></div><div class="panel-body"><div class="tool-card"><span class="tool-symbol">▤</span><div><h3>Grant Factory</h3><p>Turn project facts into a working draft.</p></div><button data-action="grants" aria-label="Open Grant Factory">↗</button></div><div class="tool-card"><span class="tool-symbol green">◎</span><div><h3>LumaScout</h3><p>Find sources, partners, and opportunities.</p></div><button data-action="scout" aria-label="Open LumaScout">↗</button></div><div class="tool-card"><span class="tool-symbol amber">⌁</span><div><h3>Paper Lab</h3><p>Explore a trading rule with fictional funds.</p></div><button data-action="paper" aria-label="Open Paper Lab">↗</button></div><div class="tool-card"><span class="tool-symbol green">✳</span><div><h3>Luma Assistant</h3><p>Prepare next steps from your own facts.</p></div><button data-action="assistant" aria-label="Open Luma Assistant">↗</button></div></div></section></div>
<div class="context-note"><span aria-hidden="true">◉</span><p><strong>Start with what is true.</strong> These three ideas come from public research. Your current tools, workload and results still need your input. Work you enter stays in this browser unless you export it or choose an AI action.</p></div>${sourceLinks()}`;}
function workboard(){return heading('A clearer next step for every job.','Keep the brief, acceptance criteria, revision and owner decision together.',button('Review workflow','review-work')+button('+ Add work item','new-item',true))+`<div class="workboard">${STAGES.map(stage=>`<section class="work-column"><h3>${STAGE_NAMES[stage]} <span>${state.items.filter(i=>i.stage===stage).length}</span></h3>${state.items.filter(i=>i.stage===stage).map(i=>`<article class="work-item"><h4>${esc(i.title)}</h4><p>${esc(i.scope||'Scope still needed')}</p><span class="badge ${i.approved?'':'amber'}">${i.approved?'OWNER ACCEPTED':'NEEDS REVIEW'}</span><p style="margin-top:10px">${esc(i.due||'No planned date')} · ${esc(i.revision||'No revision')}</p><button class="btn" data-edit-item="${esc(i.id)}">Open brief</button><label>Move to<select data-stage-item="${esc(i.id)}">${STAGES.map(s=>`<option value="${s}" ${i.stage===s?'selected':''}>${STAGE_NAMES[s]}</option>`).join('')}</select></label></article>`).join('')||'<p class="muted small">No items here yet.</p>'}</section>`).join('')}</div><div class="context-note"><p>Review checks flag missing requirements and unrecorded approvals. They do not change a job, accept a design, or contact a customer.</p></div>${state.reviews.length?`<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Latest workflow review</h2><span class="badge neutral">RULE CHECK</span></div><div class="panel-body">${reviewList(state.reviews.at(-1).findings)}</div></section>`:''}`;}
function reviewList(findings){return findings.length?findings.map(f=>`<p class="small"><strong>${esc(f.title||f.id)}</strong> · ${esc(f.message)}</p>`).join(''):'<p class="small muted">No missing fields were found by these checks. Owner review still determines whether the work is ready.</p>';}
function measure(){return heading('Measure the whole job.','Compare equivalent accepted output, including failures, rework, warm-up and supporting equipment.',button('+ Record a baseline','new-measure',true))+`<div class="card-grid">${member.hypotheses.map((h,i)=>`<article class="card"><span class="badge neutral">MEASUREMENT ${i+1}</span><h3>${esc(h.metric)}</h3><p>${esc(h.measurement_plan)}</p><p class="small">Unit: ${esc(h.unit)}</p><button class="btn" data-hypothesis="${i}">See method ↗</button></article>`).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Energy per accepted part</h2><span class="badge amber">OWNER MEASUREMENTS</span></div><div class="panel-body"><p class="muted small">Enter complete-batch metered Wh. Additional overhead is only energy outside that measured boundary. Comparisons require the same accepted output and operating conditions.</p><form id="energy-form"><div class="form-grid">${[['baseline_wh','Baseline batch energy (Wh)'],['candidate_wh','Candidate batch energy (Wh)'],['baseline_attempted','Baseline attempted parts'],['candidate_attempted','Candidate attempted parts'],['baseline_accepted','Baseline accepted parts'],['candidate_accepted','Candidate accepted parts'],['overhead_wh','Candidate overhead outside the meter (Wh)']].map(([k,l])=>`<label>${l}<input name="${k}" type="number" min="0" max="1000000000000" step="${k.includes('wh')?'any':'1'}" required ${k==='overhead_wh'?'value="0"':''}></label>`).join('')}<label>Measurement source / boundary<input name="source" required maxlength="600" placeholder="Meter, batch IDs, dates and equipment included"></label><label class="checkbox full"><input name="equivalent" type="checkbox">The same accepted part specification and operating conditions apply to both complete batches.</label><label class="checkbox full"><input name="boundary_complete" type="checkbox">All production energy, failures, rework, warm-up and auxiliaries are included; overhead is not counted twice.</label></div><div class="form-actions"><button class="btn primary" type="submit">Calculate and keep record</button></div></form><div id="energy-result"></div></div></section>${state.measurements.length?`<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Saved measurements</h2></div><div class="panel-body">${state.measurements.slice(-10).reverse().map(m=>`<p class="small"><strong>${esc(m.title||m.metric||'Energy comparison')}</strong> · ${esc(m.recorded_at)}<br><span class="muted">${esc(m.source||m.notes||'')} · ${esc(m.result?.status||m.value||'Observation recorded')}</span></p>`).join('')}</div></section>`:''}`;}
function grants(){return heading('Build the facts before the application.','Create a member-specific working draft and keep unknown facts visible.',button('+ Create grant draft','new-grant',true))+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Your grant drafts</h2><span class="badge">${state.grants.length} SAVED</span></div><div class="panel-body">${state.grants.length?state.grants.map(g=>`<article class="tool-card"><span class="tool-symbol">▤</span><div><h3>${esc(g.title)}</h3><p>Draft · ${esc(g.recorded_at)}</p></div><button data-grant-download="${esc(g.id)}" aria-label="Download ${esc(g.title)}">↓</button></article>`).join(''):`<div class="empty"><h3>Your next project starts with a clear brief.</h3><p>Add the opportunity, your project, known costs and evidence. Missing applicant facts remain marked for you to complete.</p>${button('Create a working draft','new-grant',true)}</div>`}</div></section><section class="card"><span class="badge violet">DISCOVER</span><h3>Start at the official source.</h3><p>Search grants, contracts and local support. Relevance does not establish eligibility; review the current notice with the authorized applicant.</p><div class="button-row"><a class="btn" href="https://www.grants.gov/search-grants" target="_blank" rel="noopener noreferrer">Grants.gov ↗</a><a class="btn" href="https://sam.gov/opportunities" target="_blank" rel="noopener noreferrer">SAM.gov ↗</a><button class="btn" data-action="scout">Open LumaScout</button></div></section></div>`;}
function scout(){const q=encodeURIComponent(`${member.industry} grants partnerships Tennessee`);return heading('Find the next useful connection.','Keep opportunities, evidence links and your next step in one place.',button('+ Save opportunity','new-scout',true))+`<div class="card-grid"><article class="card"><span class="badge">FUNDING</span><h3>Public funding sources</h3><p>Search current official listings using your project language.</p><a class="btn" href="https://www.grants.gov/search-grants" target="_blank" rel="noopener noreferrer">Search Grants.gov ↗</a></article><article class="card"><span class="badge violet">COMMUNITY</span><h3>A strength already in the room</h3><p>Explore the other TakeOff businesses and the capabilities described in their public sources.</p>${button('Find a cohort business ↗','directory')}</article><article class="card"><span class="badge amber">RESEARCH</span><h3>Find a source worth checking</h3><p>A starting search for ${esc(member.industry.toLowerCase())}. Verify identity and current details before acting.</p><a class="btn" href="https://www.google.com/search?q=${q}" target="_blank" rel="noopener noreferrer">Open public search ↗</a></article></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Saved opportunities</h2>${runtime?button('Scan official grants','scan-grants'):''}</div><div class="panel-body">${state.scout.length?`<div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Source</th><th>Next step</th><th>State</th></tr></thead><tbody>${state.scout.map(s=>`<tr><td>${esc(s.title)}</td><td>${safeLink(s.url,'Open source ↗')}</td><td>${esc(s.next_step||'Review current official details')}</td><td><span class="badge neutral">${esc(s.status||'TO REVIEW')}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No saved opportunities yet.</h3><p>Add a source you want to investigate. The downloaded runtime can also retrieve and rank public Grants.gov listings by topic.</p></div>'}</div></section>`;}
function safeLink(url,label){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw 0;return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${label}</a>`;}catch{return '<span class="muted">Source needed</span>';}}
function paper(){return heading('Learn how a trading rule behaves.','A transparent 5/20 moving-average baseline with fictional funds, fees and next-open fills.',button('Download example CSV','example-csv'))+`<div class="context-note" style="margin-top:0;margin-bottom:22px"><p><strong>Paper trading only.</strong> The included price series is fabricated for learning. Import your own authorized daily data to test it. This tool does not place broker orders, predict profits, or use your business capital.</p></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Run a paper simulation</h2><span class="badge amber">NO LIVE ORDERS</span></div><div class="panel-body"><form id="paper-form"><div class="form-grid"><label>Starting fictional cash (USD)<input name="cash" type="number" min="1" max="1000000000" value="10000" required></label><label>Allocation per position (%)<input name="allocation" type="number" min="1" max="100" value="25" required></label><label>Fee per fill (basis points)<input name="fee_bps" type="number" min="0" max="1000" value="10" required></label><label>Slippage per fill (basis points)<input name="slippage_bps" type="number" min="0" max="1000" value="5" required></label><label class="full">Daily price CSV (date,open,close)<input id="price-file" type="file" accept=".csv,text/csv"><p id="price-source" class="form-hint">Fabricated example · 100 days · no market performance claim.</p></label></div><div class="form-actions"><button class="btn primary" type="submit">Run simulation</button></div></form></div></section><section class="card"><span class="eyebrow">EXPLICIT ASSUMPTIONS</span><h3 style="margin-top:17px">Every result should be inspectable.</h3><p>The rule compares the previous 5 and 20 closes and fills at the next daily open. It holds one funded long position, charges fees and slippage, and marks remaining holdings to the last close.</p><p>Cash earns no interest. Taxes, spreads beyond selected slippage, partial fills, liquidity and corporate actions are not modeled.</p></section></div><div id="paper-result">${state.paper?paperResult(state.paper):''}</div>`;}
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
function paperResult(p){return `<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Simulation result</h2><span class="badge amber">${esc(p.source||'PAPER')}</span></div><div class="panel-body"><div class="result-grid"><div class="result-tile"><span>Marked fictional equity</span><strong>${money(p.equity)}</strong></div><div class="result-tile"><span>Paper P&amp;L, including costs</span><strong>${money(p.pnl)}</strong></div><div class="result-tile"><span>Maximum observed drawdown</span><strong>${(p.drawdown*100).toFixed(2)}%</strong></div></div><canvas class="chart" id="paper-chart" aria-label="Fictional portfolio equity over the supplied daily data"></canvas><p class="small muted">${p.fills.length} modeled fills · ${money(p.fees)} fees · ${money(p.cash)} remaining cash · ${p.position.toFixed(6)} open units</p><button class="btn" data-action="export-paper">Export complete simulation ↓</button><details><summary>Inspect modeled fills</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th>Side</th><th>Quantity</th><th>Price</th><th>Fee</th></tr></thead><tbody>${p.fills.slice(-100).map(f=>`<tr><td>${esc(f.date)}</td><td>${esc(f.side)}</td><td>${f.quantity.toFixed(6)}</td><td>${money(f.price)}</td><td>${money(f.fee)}</td></tr>`).join('')}</tbody></table></div></details></div></section>`;}
function care(){return heading('Keep coordination visible.','A nonclinical practice board for pseudonymous or fictional handoffs.',button('+ Add practice handoff','new-care',true))+`<div class="context-note" style="margin-top:0;margin-bottom:22px"><p><strong>Use fictional cases or non-sensitive operational IDs.</strong> Do not enter patient names, contact details, diagnoses or clinical notes. This browser workspace is not a clinical record system or a HIPAA-certified deployment.</p></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Handoff practice board</h2>${button('Check handoffs','review-care')}</div><div class="panel-body">${state.care.length?state.care.map(c=>`<article class="tool-card"><span class="tool-symbol green">✧</span><div><h3>${esc(c.id)}</h3><p>${esc(c.owner||'Owner needed')} · ${esc(c.stage)}<br>${esc(c.next_step||'Next step needed')}</p></div><button data-care-edit="${esc(c.id)}" aria-label="Edit ${esc(c.id)}">↗</button></article>`).join(''):'<div class="empty"><h3>A handoff needs an owner and a next step.</h3><p>Practice the workflow with a fictional reference, coordination owner, status and confirmation time.</p></div>'}</div></section><section class="card"><span class="badge">COORDINATION SUPPORT</span><h3>Support the people doing the work.</h3><p>Make unresolved cases and missing confirmations visible. The checks do not select care, diagnose, prioritize medical need or replace a coordinator’s or clinician’s judgment.</p><div id="care-review"></div></section></div>`;}
function assistant(){return heading('Prepare the next useful step.','Let Luma turn a bounded task and approved facts into a reviewable working draft.')+`<div class="agent-state ${runtime?'':'offline'}"><span class="status-dot"></span>${runtime?'Your private local runtime is connected. AI requests use its configured API key.':'Use the free package to connect your own local AI runtime. The public workspace does not expose an API key.'}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Your task</h2><span class="badge violet">PUBLIC FACTS + YOUR PROMPT</span></div><div class="panel-body"><form id="assistant-form"><label>What would help you today?<textarea name="prompt" required maxlength="6000" rows="6" placeholder="Prepare a concise design-intake checklist from our public services. Keep unknown specifications as questions."></textarea></label><p class="form-hint">Only this prompt and the public member profile go to OpenAI. Workboard records and LumaCare entries are not included. Do not paste secrets or sensitive customer information.</p><div class="form-actions">${runtime?'<button class="btn primary" type="submit">Ask Luma</button>':button('Get my local package','package',true)}</div></form><div id="assistant-result" class="output" role="status" style="margin-top:20px"></div></div></section><section class="card"><span class="eyebrow">A CLEAR JOB FOR THE ASSISTANT</span><h3 style="margin-top:18px">Ground it in your strengths.</h3><p>${esc(member.strength)}</p><h3>Useful starting tasks</h3><p>Prepare an intake checklist. Draft a project narrative. Compare workflow alternatives. Identify missing evidence before a decision.</p><p class="small">Drafts remain for your review. The assistant cannot send email, submit grants, operate equipment, or place live trades.</p></section></div>`;}
function directory(){return heading('Discover the strength next door.','69 businesses from the official TakeOff Fall 2026 roster. Independent public research, open to correction.')+`<div class="filterbar"><label class="search"><span>Search the cohort</span><input id="directory-search" type="search" placeholder="Try design, education, healthcare, or a business name…"></label><label>Industry<select id="industry-filter"><option value="">All industries</option>${[...new Set(catalog.companies.map(c=>c.industry))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><div class="card-grid" id="directory-cards">${directoryCards(catalog.companies)}</div>`;}
function directoryCards(rows){return rows.map(c=>`<article class="card"><span class="badge neutral">${esc(c.industry)}</span><h3>${esc(c.name)}</h3><p>${esc(c.strength)}</p><div class="card-footer"><a class="btn" href="https://lumen-core.ai/cohort/members/${esc(c.id)}.html">Public profile ↗</a><button class="btn" data-member="${esc(c.id)}">Open workspace ↗</button>${safeLink(c.official_site,'Website ↗')}</div></article>`).join('')||'<p class="muted">No businesses match this search.</p>';}
function packageView(){if(runtime)return localPackageView();return heading('A workspace you can keep.','Your member profile, tools and private local AI runtime in one portable download.')+`<section class="hero-work"><div class="hero-copy"><span class="eyebrow">YOUR FREE LUMA PACKAGE</span><h2>${esc(member.name)}.<br>Ready for your next step.</h2><p>A private local workspace, public-source scout, grant drafts, a paper bot and measurement tools. Your own API usage is billed by your provider; the package itself is free.</p><div class="button-row"><a class="btn primary" href="./downloads/${encodeURIComponent(member.id)}.zip" download>↓ Download ${esc(member.name)} package</a>${button('Export this workspace','export')}<button class="btn" data-action="import-workspace">Import a backup</button></div></div><div class="card" style="margin:25px;background:#102032"><h3>Included in your download</h3><p>✓ Your three research opportunities<br>✓ Workboard and revision records<br>✓ Grant Factory and LumaScout<br>✓ Paper simulation and scheduled paper bot<br>✓ LumaCare coordination practice<br>✓ Private AI assistant and audit receipts</p><span class="badge">PYTHON 3.11+ · WINDOWS / MAC / LINUX</span></div></section><section class="panel"><div class="panel-head"><h2>Start on Windows</h2><button class="btn" data-action="copy-install">Copy PowerShell</button></div><div class="panel-body"><p class="muted small">This downloads your package, verifies its SHA-256, and opens its README. It does not change your execution policy or create an API key. Follow the README to start the local app.</p><pre class="code-box" id="install-code">Loading verified package information…</pre></div></section><details><summary>What is private, and what is shared?</summary><p>The public catalog contains public business descriptions and research questions. Work you enter in this website stays in your browser. Export it for backups. The downloaded app keeps records in its local folder and exposes only a loopback service. The AI assistant sends only the task and public company context you choose. No API key is bundled, and no customer or patient systems are connected.</p></details><details><summary>What is still needed for production use?</summary><p>Each business must accept its workflow, data permissions and measurement plan. Team access, business-system integrations and regulated data need an owner-approved deployment and review. This gift does not imply government certification, HIPAA compliance, a funded grant, or trading profitability.</p></details>`;}
function render(){rendererCleanup();rendererCleanup=()=>{};$('#crumb').textContent=VIEWS[view];$$('#workspace-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.toggleAttribute('aria-current',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');});const builders={overview,workboard,measure,grants,scout,paper,care,assistant,directory,package:packageView};$('#view').innerHTML=builders[view]();bindView();if(view==='overview')drawFlow();if(view==='paper'&&state.paper)drawPaper();if(view==='package')loadInstaller();if(runtime&&['paper','scout','assistant'].includes(view))loadActivity();}
function download(name,text,type='application/json'){const blob=new Blob([text],{type});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportState(){download(`${member.id}-workspace.json`,JSON.stringify(state,null,2));toast('Workspace backup downloaded.');}
function field(name,label,value='',type='text',required=false){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="${name==='title'?180:600}"></label>`;}
function area(name,label,value='',max=3000){return `<label class="full">${esc(label)}<textarea name="${name}" maxlength="${max}" rows="3">${esc(value)}</textarea></label>`;}
function modal(title,body,onSubmit){const d=$('#edit-dialog');$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-button" type="button" id="edit-close" aria-label="Close">×</button></div><form id="edit-form">${body}<div class="form-actions"><button type="button" class="btn" id="edit-cancel">Cancel</button><button type="submit" class="btn primary">Save</button></div></form>`;$('#edit-close').onclick=$('#edit-cancel').onclick=()=>d.close();$('#edit-form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(new FormData(e.target),e.target);d.close();save();render();}catch(error){toast(error.message);}};d.showModal();}
function newItem(existing){const i=existing||{title:'',scope:'',acceptance:'',revision:'',stage:'inbox',due:'',approved:false};modal(existing?'Review work brief':'Add a work brief',`<div class="form-grid">${field('title','Work item title',i.title,'text',true)}${field('due','Planned completion',i.due,'date')}${area('scope',member.id==='excalis'?'Dimensions, intended use, material and delivery scope':'Scope and required inputs',i.scope)}${area('acceptance','How the owner will accept this work',i.acceptance,2000)}${field('revision','Approved revision / version',i.revision)}${field('owner','Owner role (avoid personal data)',i.owner||'')}<label class="full">Attach a revision fingerprint<input name="revision_file" type="file"><p class="form-hint">Only the file name and SHA-256 are kept. The file is read locally and is not uploaded. Maximum 25 MB.</p>${i.file_hash?`<p class="revision-hash">${esc(i.file_hash)}</p>`:''}</label><label class="checkbox full"><input name="approved" type="checkbox" ${i.approved?'checked':''}>I am the owner or authorized reviewer and have accepted this brief and revision.</label></div>`,async f=>{const item={...i,id:i.id||crypto.randomUUID(),title:String(f.get('title')).trim(),scope:String(f.get('scope')).trim(),acceptance:String(f.get('acceptance')).trim(),due:String(f.get('due')),revision:String(f.get('revision')).trim(),owner:String(f.get('owner')).trim(),approved:f.get('approved')==='on',updated_at:new Date().toISOString()};if(!item.title)throw new Error('A title is required.');const file=f.get('revision_file');if(file&&file.size){if(file.size>25_000_000)throw new Error('Use a file below 25 MB for the browser fingerprint.');item.file_hash=await sha(file);item.file_name=file.name;}if(item.approved&&(!item.scope||!item.acceptance))throw new Error('Record scope and acceptance criteria before owner acceptance.');if(existing)state.items[state.items.findIndex(x=>x.id===i.id)]=item;else{if(state.items.length>=500)throw new Error('Export or archive work before exceeding 500 items.');state.items.push(item);}toast('Work brief saved in this browser.');});}
async function sha(file){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');}
function hypothesis(index){const h=member.hypotheses[index];modal('Explore a workflow opportunity',`<p>${esc(h.question)}</p><div class="context-note"><p>${esc(h.contribution)}</p></div><p class="muted small" style="margin-top:18px">${esc(h.boundary)}</p><p class="small"><strong>Measure:</strong> ${esc(h.metric)} (${esc(h.unit)})</p><p class="small muted">${esc(h.formula||h.measurement_plan)}</p><label>Next step to add to your workboard<textarea name="next" maxlength="3000">${esc(h.contribution)}</textarea></label>`,f=>{if(state.items.length>=500)throw new Error('Workboard limit reached.');state.items.push({id:crypto.randomUUID(),title:`Explore: ${h.metric}`.slice(0,180),scope:String(f.get('next')),acceptance:h.boundary,revision:'',due:'',approved:false,stage:'inbox',hypothesis:h.id,updated_at:new Date().toISOString()});toast('A research next step was added.');});}
function newMeasure(){modal('Record an owner observation',`<div class="form-grid">${field('metric','Metric / observation','','text',true)}${field('value','Observed value and unit','','text',true)}${field('sample','Sample size / all eligible work','','text',true)}${field('source','Source / observation window','','text',true)}${area('notes','Failures, exclusions, quality and other context')}</div>`,f=>{state.measurements.push({id:crypto.randomUUID(),...Object.fromEntries(f),recorded_at:new Date().toISOString()});toast('Observation saved. No automatic savings claim was made.');});}
function newGrant(){modal('Create a grant working draft',`<div class="form-grid">${field('opportunity','Official opportunity title','','text',true)}${field('source','Official notice URL','','url',true)}${field('deadline','Deadline from current notice (include time zone)')}${field('legal_name','Verified legal organization name')}${field('organization_type','Verified applicant organization type')}${field('requested_amount','Requested amount and currency')}${area('project','Your proposed project')}${area('beneficiaries','People served and evidence of need')}${area('milestones','Activities, milestones and timing')}${area('measurement','How results will be measured')}${area('budget','Verified costs and funding match')}${area('evidence','Authorized supporting evidence')}</div><p class="form-hint">Blank facts remain owner-to-complete markers. This creates a draft, without certifications or submission.</p>`,f=>{const facts=Object.fromEntries(f);const g={id:crypto.randomUUID(),title:facts.opportunity,facts,markdown:draftGrant(member,facts),recorded_at:new Date().toISOString()};state.grants.push(g);download(`${member.id}-grant-draft.md`,g.markdown,'text/markdown');toast('Working draft saved and downloaded.');});}
function newScout(){modal('Save an opportunity',`<div class="form-grid">${field('title','Opportunity or partner','','text',true)}${field('url','Public source URL','','url',true)}${area('next_step','Your next step')}</div>`,f=>{const u=new URL(String(f.get('url')));if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw new Error('Use a public http or https source URL.');state.scout.push({id:crypto.randomUUID(),...Object.fromEntries(f),status:'TO REVIEW',recorded_at:new Date().toISOString()});toast('Opportunity saved for review.');});}
function newCare(existing){const c=existing||{};modal('Record a practice handoff',`<p class="form-hint">Use a fictional case reference. Do not enter patient or clinical information.</p><div class="form-grid">${field('id','Fictional / non-sensitive reference',c.id||'','text',true)}${field('owner','Coordination owner role',c.owner||'')}<label>Status<select name="stage">${['requested','readiness','handoff','confirmed'].map(s=>`<option ${c.stage===s?'selected':''}>${s}</option>`).join('')}</select></label>${field('confirmed_at','Confirmation time',c.confirmed_at||'','datetime-local')}${area('next_step','Next nonclinical coordination step',c.next_step||'')}</div>`,f=>{const r=Object.fromEntries(f);if(!/^[A-Za-z0-9_.-]{1,60}$/.test(r.id))throw new Error('Use a short non-sensitive case code (letters, numbers, dash or dot).');if(r.stage==='confirmed'&&!r.confirmed_at)throw new Error('Record a confirmation time before marking a handoff confirmed.');if(existing)state.care[state.care.findIndex(x=>x.id===existing.id)]=r;else{if(state.care.some(x=>x.id===r.id))throw new Error('That reference already exists.');state.care.push(r);}toast('Practice handoff saved locally.');});}
async function api(path,payload){if(payload&&['assistant','scout','paper'].includes(path)){payload={...payload,request_id:payload.request_id||crypto.randomUUID()};}const res=await fetch(`/api/member/${path}`,{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json','X-Luma-Local':'1'}:{},body:payload?JSON.stringify(payload):undefined});const obj=await res.json();if(!res.ok)throw new Error(obj.detail||'The local service could not complete this request.');return obj;}
async function action(name){if(VIEWS[name])return show(name);if(name==='new-item')return newItem();if(name==='new-measure')return newMeasure();if(name==='new-grant')return newGrant();if(name==='new-scout')return newScout();if(name==='new-care')return newCare();if(name==='export')return exportState();if(name==='import-workspace')return importWorkspace();if(name==='review-work'){const findings=reviewWork(state.items);state.reviews.push({recorded_at:new Date().toISOString(),findings});state.reviews=state.reviews.slice(-100);save();show('workboard');toast(`${findings.length} workflow checks to review.`);}if(name==='example-csv')download('fabricated-example-prices.csv',examplePrices(),'text/csv');if(name==='export-paper'&&state.paper)download(`${member.id}-paper-simulation.json`,JSON.stringify(state.paper,null,2));if(name==='run-paper-bot'){toast('Checking the public BTC-USD feed…');try{await api('paper',{member:member.id});await loadActivity();toast('Paper tick complete. No real order was placed.');}catch(e){toast(e.message);}}if(name==='review-care')$('#care-review').innerHTML=reviewList(careReview(state.care));if(name==='copy-install'){try{await navigator.clipboard.writeText($('#install-code').textContent);toast('PowerShell block copied.');}catch{toast('Select and copy the block below.');}}if(name==='scan-grants'){toast('Retrieving public listings from Grants.gov…');try{const r=await api('scout',{member:member.id,query:member.industry});for(const x of r.opportunities){if(!state.scout.some(s=>s.url===x.url))state.scout.push({...x,id:crypto.randomUUID(),next_step:'Verify current notice and applicant eligibility',status:'TO REVIEW'});}state.scout=state.scout.slice(-500);save();render();toast(`${r.opportunities.length} public listings retrieved. Relevance is not eligibility.`);}catch(e){toast(e.message);}}}
function bindView(){ $$('[data-action]',$('#view')).forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-hypothesis]').forEach(b=>b.onclick=()=>hypothesis(Number(b.dataset.hypothesis)));$$('[data-member]').forEach(b=>b.onclick=()=>{view='overview';loadMember(b.dataset.member);});$$('[data-edit-item]').forEach(b=>b.onclick=()=>newItem(state.items.find(i=>i.id===b.dataset.editItem)));$$('[data-care-edit]').forEach(b=>b.onclick=()=>newCare(state.care.find(i=>i.id===b.dataset.careEdit)));$$('[data-stage-item]').forEach(b=>b.onchange=()=>{const i=state.items.find(i=>i.id===b.dataset.stageItem);if(['in_progress','complete'].includes(b.value)&&!i.approved){toast('Record the owner’s acceptance of the brief first.');b.value=i.stage;return;}i.stage=b.value;i.updated_at=new Date().toISOString();save();render();});$$('[data-grant-download]').forEach(b=>b.onclick=()=>{const g=state.grants.find(x=>x.id===b.dataset.grantDownload);download(`${member.id}-grant-draft.md`,g.markdown,'text/markdown');});
if($('#directory-search')){$('#directory-search').oninput=$('#industry-filter').onchange=()=>{const q=$('#directory-search').value.toLowerCase(),industry=$('#industry-filter').value;$('#directory-cards').innerHTML=directoryCards(catalog.companies.filter(c=>(!industry||c.industry===industry)&&`${c.name} ${c.strength} ${c.industry}`.toLowerCase().includes(q)));$$('[data-member]').forEach(b=>b.onclick=()=>{view='overview';loadMember(b.dataset.member);});};}
if($('#energy-form'))$('#energy-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),input=Object.fromEntries([...f].map(([k,v])=>[k,k==='source'?v:k==='equivalent'||k==='boundary_complete'?v==='on':Number(v)]));const r=energyComparison(input);state.measurements.push({id:crypto.randomUUID(),title:'Energy per accepted part',source:input.source,inputs:input,result:r,recorded_at:new Date().toISOString()});save();$('#energy-result').innerHTML=`<div class="result-grid"><div class="result-tile"><span>Baseline Wh / accepted part</span><strong>${r.baseline_wh_per_accepted.toFixed(2)}</strong></div><div class="result-tile"><span>Candidate Wh / accepted part</span><strong>${r.candidate_wh_per_accepted.toFixed(2)}</strong></div><div class="result-tile"><span>${r.comparison_allowed?'Observed net Wh difference':'Comparison status'}</span><strong>${r.comparison_allowed?r.net_wh.toFixed(2):'Hold'}</strong></div></div><p class="inline-notice">${r.comparison_allowed?'Positive net Wh means less measured energy for the declared equivalent batch; negative means more. This observation is not independent validation.':'The batches are not comparable until accepted output, quality, conditions and the full energy boundary match. Per-unit ratios alone do not establish savings.'}</p>`;toast('Measurement record saved.');}catch(error){toast(error.message);}};
if($('#price-file'))$('#price-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500000)throw new Error('Use a CSV under 500 KB.');const text=await file.text();const rows=parsePriceCSV(text);paperCSV=text;$('#price-source').textContent=`Imported ${file.name} · ${rows.length} daily rows · source accuracy not independently verified`;$('#price-source').dataset.imported='yes';}catch(error){toast(error.message);e.target.value='';}};
if($('#paper-form'))$('#paper-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),params=Object.fromEntries([...f].map(([k,v])=>[k,Number(v)]));params.allocation/=100;const r=paperBacktest(parsePriceCSV(paperCSV),params);r.source=$('#price-source').dataset.imported?'OWNER-SUPPLIED DATA':'FABRICATED EXAMPLE';r.recorded_at=new Date().toISOString();state.paper=r;save();$('#paper-result').innerHTML=paperResult(r);$$('[data-action]',$('#paper-result')).forEach(b=>b.onclick=()=>action(b.dataset.action));drawPaper();}catch(error){toast(error.message);}};
if($('#assistant-form'))$('#assistant-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);if(!runtime||!b)return;b.disabled=true;$('#assistant-result').textContent='Luma is preparing a draft…';try{const r=await api('assistant',{member:member.id,prompt:new FormData(e.target).get('prompt')});$('#assistant-result').textContent=r.text;toast('Draft ready for your review.');}catch(error){$('#assistant-result').textContent=error.message;}finally{b.disabled=false;}};
}
async function loadInstaller(){if(runtime||document.querySelector('meta[name="luma-local-runtime"]'))return;try{const r=await fetch('./downloads/manifest.json');if(!r.ok)throw 0;const m=await r.json();const item=m.packages.find(x=>x.member===member.id);if(!item)throw 0;const code=`$ErrorActionPreference = 'Stop'\n$LumaFolder = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'Luma-${member.id}'\n$LumaZip = Join-Path $env:TEMP 'Luma-${member.id}.zip'\nif (Test-Path -LiteralPath $LumaFolder) { throw 'Folder already exists. Open its README instead of overwriting it.' }\nInvoke-WebRequest -Uri 'https://lumen-core.ai/cohort/downloads/${member.id}.zip' -OutFile $LumaZip\nif ((Get-FileHash -LiteralPath $LumaZip -Algorithm SHA256).Hash -ne '${item.sha256.toUpperCase()}') { throw 'Package verification failed.' }\nExpand-Archive -LiteralPath $LumaZip -DestinationPath $LumaFolder\nnotepad (Join-Path $LumaFolder 'README.txt')`;if($('#install-code'))$('#install-code').textContent=code;}catch{if($('#install-code'))$('#install-code').textContent='Package download is being prepared. The workspace tools above are available now.';}}
function drawPaper(){const c=$('#paper-chart');if(!c||!state.paper?.curve?.length)return;const ctx=c.getContext('2d');const w=c.clientWidth,h=180;c.width=w*2;c.height=h*2;ctx.scale(2,2);const vals=state.paper.curve.map(x=>x.equity),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(1,max-min);ctx.strokeStyle='#263e50';ctx.lineWidth=1;for(let i=1;i<4;i++){ctx.beginPath();ctx.moveTo(0,i*h/4);ctx.lineTo(w,i*h/4);ctx.stroke();}ctx.strokeStyle='#74edd8';ctx.lineWidth=2;ctx.beginPath();vals.forEach((v,i)=>{const x=i/(vals.length-1)*(w-4)+2,y=h-14-(v-min)/range*(h-28);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}
async function drawFlow(){const canvas=$('#flow-canvas');if(!canvas)return;const token=Symbol();canvas._token=token;try{const THREE=await import('../build_week/prooflock_console/three.module.min.js');if(!canvas.isConnected||canvas._token!==token)return;const scene=new THREE.Scene();const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));const camera=new THREE.PerspectiveCamera(38,1,.1,100);camera.position.set(0,3.5,10);camera.lookAt(0,0,0);const group=new THREE.Group();scene.add(group);const nodes=[];const materials=[];const geometries=[];const positions=[[-3.3,0,.7],[-1.7,.65,-.5],[0,0,.65],[1.7,.65,-.5],[3.3,0,.7]];for(let i=0;i<5;i++){const geo=new THREE.IcosahedronGeometry(.38,0);geometries.push(geo);const mat=new THREE.MeshBasicMaterial({color:i===2?0xa69afa:0x74edd8,wireframe:true,transparent:true,opacity:.85});materials.push(mat);const mesh=new THREE.Mesh(geo,mat);mesh.position.set(...positions[i]);group.add(mesh);nodes.push(mesh);const innerGeo=new THREE.IcosahedronGeometry(.23,0);geometries.push(innerGeo);const innerMat=new THREE.MeshBasicMaterial({color:i===2?0x8c7aea:0x2d8d85,transparent:true,opacity:.26});materials.push(innerMat);const inner=new THREE.Mesh(innerGeo,innerMat);mesh.add(inner);if(i){const lineGeo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(...positions[i-1]),new THREE.Vector3(...positions[i])]);geometries.push(lineGeo);const lineMat=new THREE.LineBasicMaterial({color:0x588f9c,transparent:true,opacity:.8});materials.push(lineMat);group.add(new THREE.Line(lineGeo,lineMat));}}
const grid=new THREE.GridHelper(12,24,0x275965,0x203b4d);grid.position.y=-.65;grid.material.transparent=true;grid.material.opacity=.3;scene.add(grid);geometries.push(grid.geometry);materials.push(grid.material);
let stopped=false,drag=false,lastX=0,angle=0,last=0,frame=0,motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;const resize=()=>{if(stopped)return;const rect=canvas.parentElement.getBoundingClientRect();renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();renderer.render(scene,camera);};const observer=new ResizeObserver(resize);observer.observe(canvas.parentElement);const pause=$('#motion-toggle');const updatePause=()=>{if(pause)pause.textContent=motion?'Pause motion':'Play motion';};updatePause();function loop(t){if(stopped||document.hidden||!motion)return;frame=requestAnimationFrame(loop);if(drag||t-last<55)return;last=t;group.rotation.y=angle+Math.sin(t/8500)*.1;nodes.forEach((n,i)=>{n.rotation.y=t/8000+i;n.rotation.z=Math.sin(t/6000+i)*.14;});renderer.render(scene,camera);}const down=e=>{drag=true;lastX=e.clientX;canvas.setPointerCapture(e.pointerId);};const move=e=>{if(!drag)return;angle+=(e.clientX-lastX)*.005;angle=Math.max(-.65,Math.min(.65,angle));lastX=e.clientX;group.rotation.y=angle;renderer.render(scene,camera);};const up=()=>drag=false;canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',up);const refreshMotion=()=>{cancelAnimationFrame(frame);if(motion&&!document.hidden&&!stopped)frame=requestAnimationFrame(loop);};document.addEventListener('visibilitychange',refreshMotion);if(pause)pause.onclick=()=>{motion=!motion;updatePause();refreshMotion();};resize();refreshMotion();rendererCleanup=()=>{stopped=true;cancelAnimationFrame(frame);document.removeEventListener('visibilitychange',refreshMotion);observer.disconnect();canvas.removeEventListener('pointerdown',down);canvas.removeEventListener('pointermove',move);canvas.removeEventListener('pointerup',up);for(const g of geometries)g.dispose();for(const m of materials)m.dispose();renderer.dispose();};}catch{if(canvas.isConnected){const ctx=canvas.getContext('2d');if(ctx){canvas.width=650;canvas.height=300;ctx.strokeStyle='#74edd8';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<5;i++){const x=75+i*125,y=130+(i%2)*35;if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y);}ctx.stroke();for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(75+i*125,130+(i%2)*35,14,0,Math.PI*2);ctx.stroke();}}if($('#motion-toggle'))$('#motion-toggle').textContent='Static workflow view';}}}
async function init(){try{const res=await fetch('./catalog.json');if(!res.ok)throw new Error('The cohort catalog could not be loaded.');catalog=await res.json();if(!Array.isArray(catalog.companies)||!catalog.companies.length)throw new Error('The cohort catalog is empty.');view=VIEWS[location.hash.slice(1)]?location.hash.slice(1):'overview';loadMember(new URLSearchParams(location.search).get('member'));$$('#workspace-nav [data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));$('#export-workspace').onclick=exportState;$('#open-package').onclick=()=>show('package');$('#company-switch').onclick=()=>{$('#company-search').value='';renderCompanySearch();$('#company-dialog').showModal();$('#company-search').focus();};$('.close-dialog').onclick=()=>$('#company-dialog').close();$('#company-search').oninput=renderCompanySearch;
if(['127.0.0.1','localhost'].includes(location.hostname)&&document.querySelector('meta[name="luma-local-runtime"]')){try{const status=await api('status');runtime=status.member===member.id&&status.ready===true;if(runtime){$('#storage-state').innerHTML='<span class="status-dot"></span> Private local runtime';const saved=await api('workspace');if(saved.workspace&&!state.items.length&&!state.grants.length&&!state.measurements.length&&!state.scout.length&&!state.care.length&&!state.paper){state=validateWorkspace(saved.workspace,member.id);}save();render();}}catch{}}
}catch(e){$('#view').innerHTML=`<div class="empty"><h1>Workspace unavailable</h1><p>${esc(e.message)}</p><button class="btn" id="retry">Try again</button></div>`;$('#retry').onclick=()=>location.reload();}}
function renderCompanySearch(){const q=$('#company-search').value.toLowerCase();const rows=catalog.companies.filter(c=>`${c.name} ${c.industry} ${c.strength}`.toLowerCase().includes(q));$('#company-results').innerHTML=rows.map(c=>`<button class="company-result" data-company="${esc(c.id)}"><strong>${esc(c.name)}</strong><small>${esc(c.industry)}</small></button>`).join('')||'<p class="muted">No matching business.</p>';$$('[data-company]').forEach(b=>b.onclick=()=>{$('#company-dialog').close();view='overview';loadMember(b.dataset.company);});}
function importWorkspace(){modal('Import your saved workspace',`<p class="muted small">The file must belong to ${esc(member.name)}. Export your current workspace before replacing it.</p><label>Workspace backup<input type="file" name="backup" accept=".json,application/json" required></label><label class="checkbox" style="margin-top:16px"><input name="replace" type="checkbox" required>I have a backup and want to replace the records in this browser.</label>`,async f=>{const file=f.get('backup');if(!file||file.size>1000000)throw new Error('Use a backup under 1 MB.');const checked=validateWorkspace(JSON.parse(await file.text()),member.id);state=checked;toast('Member backup imported.');});}
function localPackageView(){return heading('Your private package is running.','This workspace belongs to '+member.name+'. Keep backups before changing computers.')+`<section class="panel"><div class="panel-head"><h2>Your records, under your control</h2><span class="badge">LOCAL RUNTIME CONNECTED</span></div><div class="panel-body"><p class="muted">Changes are stored in this browser and backed up to the local app folder. Export a workspace file to move your records. An import must match this member and replaces this browser’s current records.</p><div class="button-row">${button('Export this workspace','export',true)}${button('Import a backup','import-workspace')}<a class="btn" href="https://lumen-core.ai/cohort/?member=${member.id}" target="_blank" rel="noopener noreferrer">Public member workspace ↗</a></div><div class="context-note"><p>The Python terminal must stay open for the assistant and scheduled tasks. Ctrl+C stops it. API keys stay in the local process; no key is saved in this package. Use fictional or non-sensitive information in LumaCare.</p></div></div></section>`;}
async function loadActivity(){try{const currentView=view;const r=await api('activity');if(view!==currentView)return;let container=$('#runtime-activity');if(!container){container=document.createElement('section');container.id='runtime-activity';container.className='panel';container.style.marginTop='22px';$('#view').append(container);}const paperJob=r.schedules.paper||{},scoutJob=r.schedules.scout||{};container.innerHTML=`<div class="panel-head"><h2>Local scheduled tools</h2><span class="badge">RUN WHILE THIS APP IS OPEN</span></div><div class="panel-body"><p class="muted small">Each enabled tool checks at most once an hour. AI drafting runs only when you ask. Closing the Python process stops scheduled work.</p><div class="form-grid"><label class="checkbox"><input type="checkbox" data-schedule="scout" ${scoutJob.enabled?'checked':''}>Check public grant listings hourly</label><label class="checkbox"><input type="checkbox" data-schedule="paper" ${paperJob.enabled?'checked':''}>Run the BTC-USD paper bot hourly</label></div><div class="button-row" style="margin-top:20px">${button('Run one paper tick','run-paper-bot')}${button('Check public grants','scan-grants')}<button class="btn" id="refresh-activity">Refresh results</button><button class="btn" id="export-audit">Export audit</button></div>${r.paper?`<div class="result-grid"><div class="result-tile"><span>Paper cash (USD)</span><strong>${money(Number(r.paper.audit.cash))}</strong></div><div class="result-tile"><span>Paper equity (USD)</span><strong>${money(Number(r.paper.audit.equity))}</strong></div><div class="result-tile"><span>Latest modeled action</span><strong>${esc(r.paper.action)}</strong></div></div><p class="muted small">${esc(r.paper.ledger.as_of_utc)} · ${r.paper.audit.paper_fills} fictional fills · 10,000 fictional starting USD · no broker connection</p>`:'<p class="muted small" style="margin-top:20px">No public-feed paper tick has completed.</p>'}${r.scout?`<p class="small">Latest public scout: ${r.scout.opportunities.length} listings · ${esc(r.scout.source_receipt.retrieved_utc)}</p>`:''}${Object.values(r.errors||{}).filter(Boolean).map(e=>`<p class="inline-notice">${esc(e.utc)}: ${esc(e.message)}</p>`).join('')}</div>`;$$('[data-action]',container).forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-schedule]',container).forEach(b=>b.onchange=async()=>{try{await api('schedule',{member:member.id,kind:b.dataset.schedule,enabled:b.checked});toast(b.checked?'Hourly local task enabled. First check is in one hour.':'Scheduled task stopped.');}catch(e){b.checked=!b.checked;toast(e.message);}});$('#refresh-activity').onclick=loadActivity;$('#export-audit').onclick=async()=>{try{download(`${member.id}-local-audit.json`,JSON.stringify(await api('audit'),null,2));}catch(e){toast(e.message);}};}catch(e){toast(e.message);}}
init();
